actions.script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import org.moqui.resource.ResourceReference

String activeUserId = userId ?: ec.user.getUserId() ?: "system_ide_user"

// 1. Check physical file last modified timestamp
long diskLastModified = 0
ResourceReference rr = ec.resource.getLocationReference(artifactUri)
if (rr != null && rr.exists) {
    diskLastModified = rr.getLastModified()
}

// 2. Fetch existing WorkspaceBuffer record
def bufferList = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
    .condition("artifactUri", artifactUri)
    .condition("userId", activeUserId)
    .orderBy("-lastUpdatedStamp")
    .useCache(false)
    .list()

def bufferRow = bufferList ? bufferList[0] : null

boolean forceReload = forceReloadFromDisk
if (bufferRow != null && diskLastModified > 0) {
    long bufferTime = bufferRow.lastUpdatedStamp ? bufferRow.lastUpdatedStamp.time : 0
    // If physical XML file on disk was modified AFTER the buffer was saved
    if (diskLastModified > bufferTime) {
        ec.logger.info("🔄 [get#WorkspaceBuffer] Disk file is newer than buffer (${diskLastModified} > ${bufferTime}). Invalidating stale buffer for: ${artifactUri}")
        forceReload = true
    }
}

boolean isStubOrEmpty = false
if (bufferRow?.metaJsonBuffer && !forceReload) {
    String rawJson = bufferRow.metaJsonBuffer
    if (rawJson.contains('"children":[]') && !rawJson.contains('form-single') && !rawJson.contains('field')) {
        isStubOrEmpty = true
    }
} else {
    isStubOrEmpty = true
}

if (!isStubOrEmpty && bufferRow?.metaJsonBuffer && !forceReload) {
    context.workspaceBufferId = bufferRow.workspaceBufferId
    context.metaJsonBuffer = bufferRow.metaJsonBuffer
    context.isDiskNewer = false
} else {
    // Fall back to reading physical XML file from disk
    ec.logger.info("📄 [get#WorkspaceBuffer] Parsing fresh XML tree from disk for: ${artifactUri}")
    Map parseResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.parse#XmlToTree")
        .parameter("artifactUri", artifactUri)
        .call()

    if (parseResult?.layoutTree) {
        String jsonFromDisk = JsonOutput.toJson(parseResult.layoutTree)

        Map storeResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer")
            .parameters([
                workspaceBufferId: bufferRow?.workspaceBufferId,
                artifactUri: artifactUri, 
                userId: activeUserId, 
                metaJsonBuffer: jsonFromDisk
            ])
            .call()

        context.workspaceBufferId = storeResult.workspaceBufferId
        context.metaJsonBuffer = jsonFromDisk
        context.isDiskNewer = true
    }
}

String activeUserId = userId ?: ec.user.getUserId() ?: "system_ide_user"
String targetBufferId = workspaceBufferId

// Self-Healing Primary Key Resolution (Fetch newest)
if (!targetBufferId) {
    def existingList = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
        .condition("artifactUri", artifactUri)
        .condition("userId", activeUserId)
        .orderBy("-lastUpdatedStamp")
        .list()
    if (existingList) {
        targetBufferId = existingList[0].workspaceBufferId
    }
}

def bufferValue = null
if (targetBufferId) {
    bufferValue = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
        .condition("workspaceBufferId", targetBufferId)
        .one()
}   
if (bufferValue) {
    bufferValue.metaJsonBuffer = metaJsonBuffer
    bufferValue.lastUpdatedStamp = ec.user.nowTimestamp
    bufferValue.update()
    ec.logger.info("💾 [store#WorkspaceBuffer] Updated DB row [${targetBufferId}] for URI: ${artifactUri}")
} else {
    bufferValue = ec.entity.makeValue("org.moqui.ai.WorkspaceBuffer")
    bufferValue.artifactUri = artifactUri
    bufferValue.userId = activeUserId
    bufferValue.metaJsonBuffer = metaJsonBuffer
    bufferValue.setSequencedIdPrimary()
    bufferValue.create()
    targetBufferId = bufferValue.workspaceBufferId
    ec.logger.info("💾 [store#WorkspaceBuffer] Created DB row [${targetBufferId}] for URI: ${artifactUri}")
}

context.workspaceBufferId = targetBufferId

                import org.moqui.resource.ResourceReference
                import java.util.regex.Matcher
                import java.util.regex.Pattern

                // Internal recursive helper to resolve <#include ...> statements
                def resolveFtlIncludes
                resolveFtlIncludes = { String loc, Set<String> visited ->
                    if (!loc) return ""

                    ResourceReference rr = ec.resource.getLocationReference(loc)
                    if (rr == null || !rr.exists) {
                        ec.logger.warn("FTL source target not found at location: ${loc}")
                        return ""
                    }

                    String canonicalPath = rr.getUrl()?.toString() ?: loc
                    if (visited.contains(canonicalPath)) {
                        ec.logger.warn("Circular FTL inclusion detected and skipped: ${canonicalPath}")
                        return "<!-- Circular include omitted: ${loc} -->"
                    }
                    visited.add(canonicalPath)

                    String content = rr.getText()
                    if (!content) return ""

                    Pattern includePattern = Pattern.compile("<#include\\s+[\"']([^\"']+)[\"'][^>]*\\/?>", Pattern.CASE_INSENSITIVE)
                    Matcher matcher = includePattern.matcher(content)
                    StringBuffer expandedContent = new StringBuffer()

                    while (matcher.find()) {
                        String includePath = matcher.group(1)
                        String resolvedLocation

                        if (includePath.contains("://") || includePath.startsWith("/")) {
                            resolvedLocation = includePath
                        } else {
                            ResourceReference parentRef = rr.getParent()
                            resolvedLocation = parentRef != null ? "${parentRef.location}/${includePath}" : includePath
                        }

                        String embeddedXml = resolveFtlIncludes(resolvedLocation, visited)
                        matcher.appendReplacement(expandedContent, Matcher.quoteReplacement(embeddedXml))
                    }
                    matcher.appendTail(expandedContent)
                    return expandedContent.toString()
                }

                // Helper to escape standard XML attributes
                def escapeXml = { String str ->
                    if (!str) return ""
                    return str.replace("&", "&amp;")
                              .replace("<", "&lt;")
                              .replace(">", "&gt;")
                              .replace("\"", "&quot;")
                              .replace("'", "&apos;")
                }

                def ignoredAttributes = [
                    '_moquiTag', 'tagName', 'type', '@type', 'mariaId', 'id', 'attributes', 
                    'ai-intent', 'children', 'widgets', 'subscreens', 'screen', 'location', 'pathIndex'
                ]

                // Recursive XML node generator
                def buildXmlNode
                buildXmlNode = { Map nodeMap, int indentLevel ->
                    if (!nodeMap) return ""

                    String rawTag = nodeMap._moquiTag ?: nodeMap.tag ?: nodeMap.tagName ?: nodeMap.type ?: nodeMap['@type']
                    if (!rawTag && nodeMap.name && (nodeMap.children || nodeMap.attributes || nodeMap.name.contains("-"))) {
                        rawTag = nodeMap.name
                    }
                    rawTag = (rawTag ?: "container").toString().replaceAll("^@", "")

                    // Avoid duplicating root wrappers
                    if (rawTag == "screen" || rawTag == "widgets") {
                        StringBuilder rootSb = new StringBuilder()
                        List rootChildren = []
                        if (nodeMap.children instanceof List) rootChildren.addAll(nodeMap.children)
                        if (nodeMap.widgets instanceof List) rootChildren.addAll(nodeMap.widgets)

                        rootChildren.each { Object child ->
                            if (child instanceof Map) rootSb.append(buildXmlNode((Map) child, indentLevel))
                        }
                        return rootSb.toString()
                    }

                    String tagName = rawTag
                    String indent = "    " * indentLevel
                    StringBuilder sb = new StringBuilder("${indent}<${tagName}")
                    List childrenList = []

                    // Attributes map takes precedence
                    Map attrs = [:]
                    if (nodeMap.attributes instanceof Map) {
                        attrs.putAll(nodeMap.attributes as Map)
                    }

                    nodeMap.each { Object kObj, Object v ->
                        if (v == null) return
                        String k = kObj.toString()

                        if (k == 'children' || k == 'widgets') {
                            if (v instanceof List) childrenList.addAll((List) v)
                            else if (v instanceof Map) childrenList.add((Map) v)
                        } else if (!ignoredAttributes.contains(k)) {
                            if (k == 'name' && (v.toString() == rawTag || attrs.containsKey('name'))) {
                                return
                            }
                            if (!(v instanceof Map) && !(v instanceof List) && !attrs.containsKey(k)) {
                                String valStr = v.toString().trim()
                                if (valStr.length() > 0) {
                                    attrs[k] = valStr
                                }
                            }
                        }
                    }

                    attrs.each { String ak, Object av ->
                        if (av != null) {
                            sb.append(" ${ak}=\"${escapeXml(av.toString())}\"")
                        }
                    }

                    if (childrenList) {
                        sb.append(">\n")
                        childrenList.each { Object child ->
                            if (child instanceof Map) {
                                sb.append(buildXmlNode((Map) child, indentLevel + 1))
                            }
                        }
                        sb.append("${indent}</${tagName}>\n")
                    } else {
                        sb.append("/>\n")
                    }
                    return sb.toString()
                }

                // Helper to build <subscreens> XML section
                def buildSubscreensXml = { Map subsMap ->
                    if (!subsMap) return ""
                    String defaultAttr = subsMap.defaultItem ? " default-item=\"${escapeXml(subsMap.defaultItem.toString())}\"" : ""
                    StringBuilder ssb = new StringBuilder("    <subscreens${defaultAttr}>\n")

                    List subItems = subsMap.children ?: subsMap.widgets ?: []
                    subItems.each { Object item ->
                        if (item instanceof Map) {
                            String sName = item.name ?: ""
                            String sLoc = item.location ?: ""
                            String sTitle = item.menuTitle ?: ""

                            ssb.append("        <subscreens-item")
                            if (sName) ssb.append(" name=\"${escapeXml(sName)}\"")
                            if (sLoc) ssb.append(" location=\"${escapeXml(sLoc)}\"")
                            if (sTitle && sTitle != sName) ssb.append(" menu-title=\"${escapeXml(sTitle)}\"")
                            ssb.append("/>\n")
                        }
                    }
                    ssb.append("    </subscreens>\n")
                    return ssb.toString()
                }

                if (location) {
                    xmlText = resolveFtlIncludes(location, new HashSet<String>())
                } else if (layoutTree) {
                    // 🎯 SCHEMA PARTITIONING: Extract top-level screen tags vs widget body
                    List topTransitions = []
                    List topActions     = []
                    List widgetNodes    = []

                    def collectNodes
                    collectNodes = { Object nodeObj ->
                        if (!(nodeObj instanceof Map)) return
                        Map node = (Map) nodeObj
                        String tag = node.name ?: (node._moquiTag ?: (node.tagName ?: node.type ?: "")).toString().replaceAll("^@", "")

                        if (tag == "transition") {
                            topTransitions.add(node)
                        } else if (tag == "actions") {
                            topActions.add(node)
                        } else if (tag == "screen" || tag == "widgets") {
                            List ch = []
                            if (node.children instanceof List) ch.addAll(node.children)
                            if (node.widgets instanceof List) ch.addAll(node.widgets)
                            ch.each { collectNodes(it) }
                        } else {
                            widgetNodes.add(node)
                        }
                    }

                    collectNodes(layoutTree)

                    // 1. Render Top-level Transitions
                    StringBuilder transitionsSb = new StringBuilder()
                    topTransitions.each { Map tNode ->
                        transitionsSb.append(buildXmlNode(tNode, 1))
                    }

                    // 2. Render Top-level Subscreens
                    String subscreensText = ""
                    if (layoutTree.subscreens instanceof Map) {
                        subscreensText = buildSubscreensXml(layoutTree.subscreens as Map)
                    }

                    // 3. Render Top-level Actions (Screen Prepare/Actions)
                    StringBuilder actionsSb = new StringBuilder()
                    topActions.each { Map aNode ->
                        actionsSb.append(buildXmlNode(aNode, 1))
                    }

                    // 4. Render Widgets Block
                    StringBuilder widgetsSb = new StringBuilder()
                    widgetNodes.each { Map wNode ->
                        widgetsSb.append(buildXmlNode(wNode, 2))
                    }

                    xmlText = """<?xml version="1.0" encoding="UTF-8"?>
<screen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/xml-screen-3.xsd">
${transitionsSb.toString()}${subscreensText}${actionsSb.toString()}    <widgets>
${widgetsSb.toString()}    </widgets>
</screen>"""
                } else {
                    xmlText = ""
                }

import groovy.json.JsonSlurper
import groovy.xml.XmlUtil
import groovy.xml.XmlParser

org.moqui.resource.ResourceReference rr = ec.resource.getLocationReference(artifactUri)
if (rr == null || !rr.exists) {
    ec.logger.error("❌ Cannot write XML file: ResourceLocation ${artifactUri} does not exist.")
    context.status = "FILE_NOT_FOUND"
    return
}

Map layoutTree
if (metaJsonBuffer instanceof Map) {
    layoutTree = (Map) metaJsonBuffer
} else if (metaJsonBuffer instanceof CharSequence && metaJsonBuffer.toString().trim().startsWith('{')) {
    layoutTree = new JsonSlurper().parseText(metaJsonBuffer.toString()) as Map
} else {
    ec.logger.error("❌ Invalid JSON payload provided to save#ScreenXml: ${metaJsonBuffer}")
    context.status = "INVALID_PAYLOAD"
    return
}

Map compileResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.compile#TreeToXml")
    .parameter("layoutTree", layoutTree)
    .call()

String rawXml = compileResult.xmlText

if (rawXml && rawXml.trim().length() > 0) {
    // 🛡️ Pre-Commit Validation Pass via MCP Screen Tools Router
    try {
        Map valResult = ec.service.sync().name("org.moqui.ai.mcp.McpToolServices.call#Tool").parameters([
            name     : 'agi-ide__screen__validate_ScreenXml',
            arguments: [rawXmlContent: rawXml, artifactUri: artifactUri, enforceHipaa: true]
        ]).call()

        if (valResult?.content && valResult.content[0]?.text) {
            Map valData = new JsonSlurper().parseText(valResult.content[0].text) as Map
            if (valData.isValid == false) {
                String errorMsg = "Screen XML validation failed: " + (valData.errors ?: []).join("; ")
                ec.logger.error("❌ [save#ScreenXml] " + errorMsg)
                ec.message.addError(errorMsg)
                context.status = "VALIDATION_FAILED"
                return
            }
            if (valData.warnings) {
                ec.logger.warn("⚠️ [save#ScreenXml] Compliance warnings: " + valData.warnings.join("; "))
            }
        }
    } catch (Exception valEx) {
        ec.logger.warn("⚠️ [save#ScreenXml] Validation service check skipped or threw error: ${valEx.message}")
    }

    String prettyXml = rawXml
    try {
        def parsedXml = new groovy.xml.XmlParser(false, false).parseText(rawXml)
        prettyXml = XmlUtil.serialize(parsedXml)
    } catch (Exception formatEx) {
        ec.logger.warn("⚠️ Could not pretty-print XML, writing raw output instead: ${formatEx.message}")
    }

    rr.putText(prettyXml)
    ec.logger.info("💾 [save#ScreenXml] Successfully written validated XML to file: ${rr.getUrl()}")
    context.status = "SUCCESS"
    context.savedFilePath = rr.getUrl()
} else {
    ec.logger.error("❌ XML Compilation generated an empty output. Save aborted to prevent file corruption.")
    context.status = "COMPILATION_ERROR"
}

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.security.MessageDigest
import org.moqui.resource.ResourceReference

def generateFallbackId = { String uri, String xpath ->
    String raw = "${uri}#${xpath}"
    MessageDigest md = MessageDigest.getInstance("MD5")
    byte[] digest = md.digest(raw.getBytes("UTF-8"))
    String hex = digest.encodeHex().toString().substring(0, 12)
    return "maria_${hex}"
}

def enrichAstNodes
enrichAstNodes = { Map node, String currentPath, int childIdx ->
    if (!node) return

    String tagName = node._moquiTag ?: (node.tagName ?: node.type ?: node['@type'] ?: "node").toString().replaceAll("^@", "")
    String explicitId = node.id ?: node.name ?: node.attributes?.name ?: node.attributes?.id

    String elementPath = "${currentPath}/${tagName}[${childIdx}]"
    if (explicitId) elementPath += "@${explicitId}"

    if (!node.mariaId) {
        if (explicitId) {
            node.mariaId = "maria_${explicitId.replaceAll('[^a-zA-Z0-9_]', '_')}"
        } else {
            node.mariaId = generateFallbackId(artifactUri, elementPath)
        }
    }

    List childrenList = []
    if (node.children instanceof List) childrenList.addAll(node.children)
    if (node.widgets instanceof List) childrenList.addAll(node.widgets)

    int idx = 0
    childrenList.each { Object child ->
        if (child instanceof Map) {
            enrichAstNodes((Map) child, elementPath, idx++)
        }
    }
}

// Helper for pure XML to AST parsing when FTL macro rendering truncates
def parseXmlNodeDirect
parseXmlNodeDirect = { groovy.util.Node xmlNode ->
    Map m = [
        _moquiTag : xmlNode.name()?.toString(),
        name      : xmlNode.name()?.toString(),
        attributes: xmlNode.attributes() ?: [:],
        children  : []
    ]
    xmlNode.children().each { child ->
        if (child instanceof groovy.util.Node) {
            m.children.add(parseXmlNodeDirect(child))
        }
    }
    return m
}

try {
    Map finalTree = null
    String qmetaOutput = ""

    // 1. Try QMETA FTL Screen Macro Render
    try {
        ec.contextStack.push()
        ec.contextStack.put("rawJsonOnly", true)
        qmetaOutput = ec.screen.makeRender()
            .rootScreen(artifactUri)
            .renderMode("qmeta")
            .macroTemplate("component://agi-ai/template/screen-macro/DefaultScreenMacros.qmeta.ftl")
            .lastStandalone("0")
            .render()
    } catch (Exception renderEx) {
        ec.logger.warn("⚠️ [parse#XmlToTree] QMETA macro render failed, falling back to direct XML parse: ${renderEx.message}")
    } finally {
        ec.contextStack.pop()
    }

    if (qmetaOutput && qmetaOutput.trim().startsWith('{')) {
        try {
            Map rawTree = new JsonSlurper().parseText(qmetaOutput.trim()) as Map
            String jsonStr = JsonOutput.toJson(rawTree)
            if (jsonStr.contains('form-single') || jsonStr.contains('form-list') || jsonStr.contains('field')) {
                finalTree = rawTree
            }
        } catch (Exception parseEx) {
            ec.logger.warn("⚠️ [parse#XmlToTree] JSON parse of qmeta macro failed, falling back to direct XML parsing: ${parseEx.message}")
            finalTree = null
        }
    }

    // 2. Direct Declarative Fallback if QMETA output is empty or truncated
    if (finalTree == null) {
        ec.logger.info("📄 [parse#XmlToTree] Parsing direct XML AST from disk for: ${artifactUri}")
        ResourceReference rr = ec.resource.getLocationReference(artifactUri)
        if (rr != null && rr.exists) {
            groovy.xml.XmlParser parser = new groovy.xml.XmlParser(false, false)
            parser.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
            groovy.util.Node rootXml = parser.parseText(rr.getText())

            List rootChildren = []
            rootXml.children().each { ch ->
                if (ch instanceof groovy.util.Node) rootChildren.add(parseXmlNodeDirect(ch))
            }

            finalTree = [
                _moquiTag : "screen",
                screen    : artifactUri.replaceAll('^component://[^/]+/screen/', '').replaceAll('\\.xml$', ''),
                location  : artifactUri,
                children  : rootChildren
            ]
        }
    }

    if (finalTree != null) {
        // 3. Populate <subscreens>
        org.moqui.impl.screen.ScreenDefinition sDef = ec.screen.getScreenDefinition(artifactUri)
        if (sDef) {
            org.moqui.util.MNode subsNode = sDef.getSubscreensNode()
            if (subsNode != null && subsNode.children("subscreens-item").size() > 0) {
                List subItemsList = []
                for (org.moqui.util.MNode subItemNode in subsNode.children("subscreens-item")) {
                    subItemsList.add([
                        _moquiTag: "subscreens-item",
                        "@type": "m-subscreens-item",
                        name: subItemNode.attribute("name") ?: "",
                        location: subItemNode.attribute("location") ?: "",
                        menuTitle: subItemNode.attribute("menu-title") ?: subItemNode.attribute("name") ?: ""
                    ])
                }
                finalTree.subscreens = [
                    _moquiTag: "subscreens",
                    defaultItem: subsNode.attribute("default-item") ?: "",
                    children: subItemsList
                ]
            }
        }

        // 4. Enrich with canonical mariaIds
        enrichAstNodes(finalTree, "", 0)

        context.layoutTree = finalTree
        ec.logger.info("✅ [parse#XmlToTree] Successfully parsed and stamped AST for: ${artifactUri}")
    } else {
        ec.logger.error("❌ [parse#XmlToTree] Failed to build AST for: ${artifactUri}")
    }

} catch (Exception e) {
    ec.logger.error("❌ [parse#XmlToTree] Error in parse#XmlToTree for ${artifactUri}", e)
    throw e
}

import java.nio.file.Path
import java.nio.file.Paths
import groovy.io.FileType

List resultList = []
String compName = targetComponent ?: 'nursinghome'
File compDir = new File("runtime/component/${compName}")

if (compDir.exists() && compDir.isDirectory()) {
    Path compBasePath = compDir.toPath()

    compDir.eachFileRecurse(FileType.FILES) { File f ->
        String filename = f.name
        if (filename.startsWith('.')) return

        Path relPath = compBasePath.relativize(f.toPath())
        String relPathStr = relPath.toString().replace('\\', '/')

        String artifactType = null
        if (filename.endsWith('.xml') && relPathStr.startsWith('screen/')) {
            artifactType = 'XML'
        } else if (filename.endsWith('.qvt.js')) {
            artifactType = 'QVT'
        } else if (relPathStr.startsWith('service/') && (filename.endsWith('Services.xml') || filename.endsWith('.groovy'))) {
            artifactType = 'SRV'
        } else if (relPathStr.startsWith('entity/') && filename.endsWith('Entities.xml')) {
            artifactType = 'ENT'
        } else if (relPathStr.startsWith('test/') && filename.endsWith('Test.xml')) {
            artifactType = 'TST'
        } else if (filename.endsWith('.ftl') || filename.endsWith('.xsl-fo')) {
            artifactType = 'RPT'
        }

        if (artifactType) {
            String fullComponentUri = "component://${compName}/${relPathStr}"
            resultList.add([
                screenName   : filename,
                label        : filename,
                artifactPath : fullComponentUri,
                value        : fullComponentUri,
                componentName: compName,
                type         : artifactType
            ])
        }
    }
}

context.artifacts = resultList

import groovy.json.JsonOutput

org.moqui.resource.ResourceReference rr = ec.resource.getLocationReference(artifactUri)
if (rr != null) {
    String formattedJson = JsonOutput.prettyPrint(JsonOutput.toJson(themeData))
    rr.putText(formattedJson)
    ec.logger.info("🎨 [save#ThemeJson] Successfully saved theme artifact: ${artifactUri}")
    context.status = "SUCCESS"
} else {
    context.status = "FILE_NOT_FOUND"
}

import groovy.json.JsonSlurper

org.moqui.resource.ResourceReference rr = ec.resource.getLocationReference(artifactUri)
if (rr != null && rr.exists) {
    String rawText = rr.getText()
    context.themeData = new JsonSlurper().parseText(rawText)
    context.status = "SUCCESS"
} else {
    context.status = "FILE_NOT_FOUND"
}

String activeUserId = userId ?: ec.user.getUserId() ?: "system_ide_user" int count = 0
if (clearAll) { count = ec.entity.find("org.moqui.ai.WorkspaceBuffer") .condition("userId", activeUserId) .deleteAll() ec.logger.info("🧹 [clear#WorkspaceBuffer] Cleared all (${count}) buffers for user: ${activeUserId}") } else if (artifactUri) { count = ec.entity.find("org.moqui.ai.WorkspaceBuffer") .condition("artifactUri", artifactUri) .deleteAll() ec.logger.info("🧹 [clear#WorkspaceBuffer] Deleted buffer record for: ${artifactUri}") }
context.status = "SUCCESS" context.deletedCount = count

import org.moqui.resource.ResourceReference

ec.logger.warn("🗑️ [delete#WorkspaceArtifact] Initiating full artifact purge for: ${artifactLocation}")

// 1. Delete physical file from disk
ResourceReference rr = ec.resource.getLocationReference(artifactLocation)
boolean fileExisted = false
boolean fileDeleted = false
if (rr != null && rr.exists) {
    fileExisted = true
    fileDeleted = rr.delete()
    ec.logger.info("🗑️ [delete#WorkspaceArtifact] Disk file deleted: ${fileDeleted} at ${artifactLocation}")
}

// 2. Clear persisted/cached workspace buffers
try {
    int count = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
            .condition("artifactUri", artifactLocation)
            .deleteAll()
    ec.logger.info("🧹 [delete#WorkspaceArtifact] Deleted ${count} DB buffer records for: ${artifactLocation}")
} catch (Exception e) {
    ec.logger.warn("⚠️ [delete#WorkspaceArtifact] Buffer record cleanup failed: ${e.message}")
}

// 3. Clear Screen & Resource Caches explicitly
try {
    ec.cache.getCache("screen.location").clear()
    ec.cache.getCache("screen.render.subscreens").clear()
    ec.cache.getCache("resource.text.location").clear()
    ec.cache.getCache("resource.template.location").clear()
} catch (Exception ignored) {
    // Ignore if signature varies
}

// 4. Invalidate Resource & Template Caches safely
try {
    ec.resource.clearAllCaches()
} catch (Exception e) {
    try {
        ec.cache.getCache("resource.text.location").clear()
        ec.cache.getCache("resource.template.location").clear()
    } catch (Exception ignored) {}
}

context.status = fileDeleted ? "SUCCESS" : (fileExisted ? "DELETE_FAILED" : "FILE_NOT_FOUND")
ec.message.addMessage("Artifact deleted successfully: ${artifactLocation}")
